INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(604665, 62749, 17720, '<td valign="top">This is an absolutely sexy photo - my only beef is the metallic bit that''s in the bottle, or behind it.  I think that it attracts too much attention, makes the writing illegible, and I really can''t see the signifigance of it.  Other than that, I like the clarity and the shape of the flames and the blue contrast.</td>', 'This is an absolutely sexy photo - my only beef is the metallic bit that''s in the bottle, or behind it.  I think that it attracts too much attention, makes the writing illegible, and I really can''t see the signifigance of it.  Other than that, I like the clarity and the shape of the flames and the blue contrast.', '2004-03-01 15:06:03.000000', NULL, 1),
(604666, 62614, 17720, '<td valign="top">This could have been very spectacular if not for the monotone purplishness.  I''m not sure if this was done purposefully or not, but I would have liked to have seen more color and contrast.</td>', 'This could have been very spectacular if not for the monotone purplishness.  I''m not sure if this was done purposefully or not, but I would have liked to have seen more color and contrast.', '2004-03-01 15:07:09.000000', NULL, 1),
