(604799, 62673, 3087, '<td valign="top">Very artistic sculpture! Very quirky.</td>', 'Very artistic sculpture! Very quirky.', '2004-03-01 16:40:54.000000', NULL, 1),
(604800, 62371, 3087, '<td valign="top">It''s clever and I like the use of the sparkler - which you''ve captured beautifully - but the sparkplug itself just isn''t a subject that holds a lot of visual interest for me.</td>', 'It''s clever and I like the use of the sparkler - which you''ve captured beautifully - but the sparkplug itself just isn''t a subject that holds a lot of visual interest for me.', '2004-03-01 16:41:54.000000', NULL, 1),
(604803, 62486, 3087, '<td valign="top">When the sun is low and heavy and red it''s certainly most redolent of fire - certainly more so than the little pinprick of pale yellow I''ve glimpsed around here lately... An interesting silhouette.</td>', 'When the sun is low and heavy and red it''s certainly most redolent of fire - certainly more so than the little pinprick of pale yellow I''ve glimpsed around here lately... An interesting silhouette.', '2004-03-01 16:43:46.000000', NULL, 1),
(604805, 62570, 3087, '<td valign="top">I don''t usually like selective desaturation but this one is very cleverly done indeed and the detail is wonderful. There''s so much to study here and yet the overall composition is strong too, with the tree, the arc of water and the repetition of the four or five men on the ground.</td>', 'I don''t usually like selective desaturation but this one is very cleverly done indeed and the detail is wonderful. There''s so much to study here and yet the overall composition is strong too, with the tree, the arc of water and the repetition of the four or five men on the ground.', '2004-03-01 16:45:27.000000', NULL, 1),
(604810, 62411, 3087, '<td valign="top">That touch of backlit cloud at the base of the tree is very redolent of fire. The sky looks like it''s been painted with a wide brush.</td>', 'That touch of backlit cloud at the base of the tree is very redolent of fire. The sky looks like it''s been painted with a wide brush.', '2004-03-01 16:49:51.000000', NULL, 1),
(604814, 62729, 3087, '<td valign="top">I think it could be improved with a touch of extra light bounced onto her face but this is an unusual and intriguing image. Makes one wonder about her story.</td>', 'I think it could be improved with a touch of extra light bounced onto her face but this is an unusual and intriguing image. Makes one wonder about her story.', '2004-03-01 16:52:09.000000', NULL, 1),
(604816, 62475, 3087, '<td valign="top">Interesting silhouette and the black of that plus the deep blue sky really provide a perfect foil for the flame. Very nice.</td>', 'Interesting silhouette and the black of that plus the deep blue sky really provide a perfect foil for the flame. Very nice.', '2004-03-01 16:52:57.000000', NULL, 1),
