INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(605202, 62371, 14606, '<td valign="top">Your spark plug idea came out so much better than mine.  very nice.   where i spent so much time trying to capture a real spark, you mimicked one with fantastic results. 10</td>', 'Your spark plug idea came out so much better than mine.  very nice.   where i spent so much time trying to capture a real spark, you mimicked one with fantastic results. 10', '2004-03-01 23:15:03.000000', NULL, 1),
(605224, 62823, 10268, '<td valign="top">I like the idea, but I can see edges of the top hand, and it just doesn''t look right.  5.</td>', 'I like the idea, but I can see edges of the top hand, and it just doesn''t look right.  5.', '2004-03-02 00:15:21.000000', NULL, 1),
(605234, 62570, 10268, '<td valign="top">I think it would have been better in all full color.  Very cool though.  7.</td>', 'I think it would have been better in all full color.  Very cool though.  7.', '2004-03-02 00:24:11.000000', NULL, 1),
(605248, 62314, 15920, '<td valign="top">The lantern is overexposed (no detail in the highlights.)  That aside, great composition.  This was a nice break fro all the flames.</td>', 'The lantern is overexposed (no detail in the highlights.)  That aside, great composition.  This was a nice break fro all the flames.', '2004-03-02 00:36:59.000000', NULL, 1),
(605264, 62002, 15920, '<td valign="top">What a great context to put this challenge in!  I have several pictures like this of my own, and appreciate the break from the other more dramatic entries.<br/> <br/>Since as is, I''d put this on my desk at work, this is only a suggestion to try: a little fill flash from the camera will lighten the shadows from the sleeping child, allow faster shutter speed (which brings in detail on the flames).  On my flash, 1/4 power never seems to wake the child, which is an added bonus.<br/> <br/>Thanks for sharing this.</td>', 'What a great context to put this challenge in!  I have several pictures like this of my own, and appreciate the break from the other more dramatic entries. Since as is, I''d put this on my desk at work, this is only a suggestion to try: a little fill flash from the camera will lighten the shadows from the sleeping child, allow faster shutter speed (which brings in detail on the flames).  On my flash, 1/4 power never seems to wake the child, which is an added bonus. Thanks for sharing this.', '2004-03-02 00:53:09.000000', NULL, 1),
(605266, 61913, 8891, '<td valign="top">lacks definition on the fire and a bit dark.</td>', 'lacks definition on the fire and a bit dark.', '2004-03-02 00:59:11.000000', NULL, 1),
(605268, 62444, 8891, '<td valign="top">nice focus on the peppers, like the sweat formed from the heat and the light play from the fire.  Just wish that the fire was more in focus thought it is rather nice from say about 3/5''s down.</td>', 'nice focus on the peppers, like the sweat formed from the heat and the light play from the fire.  Just wish that the fire was more in focus thought it is rather nice from say about 3/5''s down.', '2004-03-02 01:00:51.000000', NULL, 1),
(605270, 62339, 8891, '<td valign="top">don not like the lighting in this...the appears to be haze form by over dodging</td>', 'don not like the lighting in this...the appears to be haze form by over dodging', '2004-03-02 01:01:51.000000', NULL, 1),
(605271, 62119, 8891, '<td valign="top">You really cannot take the northern lights against so much ground light...need to be away from civilization to do it properly.  Just enough of it shows  for me to get the idea, but the city lights are so bright they really distract me totally.</td>', 'You really cannot take the northern lights against so much ground light...need to be away from civilization to do it properly.  Just enough of it shows  for me to get the idea, but the city lights are so bright they really distract me totally.', '2004-03-02 01:03:25.000000', NULL, 1),
(605273, 62559, 8891, '<td valign="top">nice embers, not too much real fire, lots of printed....interesting idea, good detail</td>', 'nice embers, not too much real fire, lots of printed....interesting idea, good detail', '2004-03-02 01:04:24.000000', NULL, 1),
(605278, 62240, 8891, '<td valign="top">Just wondering what you were going to do with that old printer, eh? The border is way too much and the picture is so- so.  The printer might have been move more towards the center of the table and I think you might have considered pulling the chairs out of the frame.</td>', 'Just wondering what you were going to do with that old printer, eh? The border is way too much and the picture is so- so.  The printer might have been move more towards the center of the table and I think you might have considered pulling the chairs out of the frame.', '2004-03-02 01:06:41.000000', NULL, 1),
(605279, 62557, 8891, '<td valign="top">nice effect, multi exposure? interesting.  Un foutunately the fire is lacking some definition due to the mult shot and the compostion could use some improvement as well.</td>', 'nice effect, multi exposure? interesting.  Un foutunately the fire is lacking some definition due to the mult shot and the compostion could use some improvement as well.', '2004-03-02 01:07:52.000000', NULL, 1),
(605281, 62548, 8891, '<td valign="top">I see you house keep about as well as I do.....nice detail, no fire but what are you going to do....heat, flame, what is the difference.  Put a piece a paper close to that baby and it is going to ignite, so the effect is the same.  Guess the purists are hammering you by now....I won''t.</td>', 'I see you house keep about as well as I do.....nice detail, no fire but what are you going to do....heat, flame, what is the difference.  Put a piece a paper close to that baby and it is going to ignite, so the effect is the same.  Guess the purists are hammering you by now....I won''t.', '2004-03-02 01:09:26.000000', NULL, 1),
(605319, 62728, 12802, '<td valign="top">Absolutely amazing picture, bugger all to do with the challenge though! :-)<br/>I really like this, good long exposure, nicely timed to get the lines perfect.  Have to mark it right down though because it''s got nothing to do with the challenge!</td>', 'Absolutely amazing picture, bugger all to do with the challenge though! :-)I really like this, good long exposure, nicely timed to get the lines perfect.  Have to mark it right down though because it''s got nothing to do with the challenge!', '2004-03-02 02:50:52.000000', NULL, 1),
