(605867, 62721, 5391, '<td valign="top">Excellent image really full of the feeling of "heat".  Fits the challenge well, nice exposure.  8</td>', 'Excellent image really full of the feeling of "heat".  Fits the challenge well, nice exposure.  8', '2004-03-02 15:34:12.000000', NULL, 1),
(605868, 62559, 5391, '<td valign="top">I like the sharpness of the image and the composition you''ve achieved.  Nice idea, clever take on the challenge.  8</td>', 'I like the sharpness of the image and the composition you''ve achieved.  Nice idea, clever take on the challenge.  8', '2004-03-02 15:34:55.000000', NULL, 1),
(605870, 62643, 5391, '<td valign="top">One of the best shots of its type in the challenge.  Nice clean lines, good focus, and the exposure is about 95% perfect - one tiny little white hot spot, but overall a very moody image that fits the challenge well.  Nice use of the entire frame.  8</td>', 'One of the best shots of its type in the challenge.  Nice clean lines, good focus, and the exposure is about 95% perfect - one tiny little white hot spot, but overall a very moody image that fits the challenge well.  Nice use of the entire frame.  8', '2004-03-02 15:36:18.000000', NULL, 1),
(605872, 62122, 5391, '<td valign="top">I love the sharpnes of those little lines, and the composition with the main portion of the flame being in the bottom right corner of the image.  Excellent exposure, good camerawork.  8</td>', 'I love the sharpnes of those little lines, and the composition with the main portion of the flame being in the bottom right corner of the image.  Excellent exposure, good camerawork.  8', '2004-03-02 15:37:21.000000', NULL, 1),
(605875, 62430, 5391, '<td valign="top">This is the best of the marshmellow shots, imho.  Good dynamic composition, and a marshmellow that''s toasted just the right amount in the spot we see.  The blown out spot where the fire is tends to be a bit of a distraction, since that is what the challenge is all about, but not a bad job for such a tricky exposure situation.</td>', 'This is the best of the marshmellow shots, imho.  Good dynamic composition, and a marshmellow that''s toasted just the right amount in the spot we see.  The blown out spot where the fire is tends to be a bit of a distraction, since that is what the challenge is all about, but not a bad job for such a tricky exposure situation.', '2004-03-02 15:39:02.000000', NULL, 1),
(605876, 62445, 5391, '<td valign="top">I really like the fluidity and abstractness of this shot.  I also like the way the flame is reflected in whatever it is sitting on.  I don''t really care too much for the little spot of flame on the right - it''s too blown out.  But the larger flame is absolutely beautiful and well captured.</td>', 'I really like the fluidity and abstractness of this shot.  I also like the way the flame is reflected in whatever it is sitting on.  I don''t really care too much for the little spot of flame on the right - it''s too blown out.  But the larger flame is absolutely beautiful and well captured.', '2004-03-02 15:40:27.000000', NULL, 1),
(605878, 62800, 5391, '<td valign="top">I really like the creativity here!  I also really like the sharpness of the image in a challenge that seemed to be lacking a lot of sharp shots, overall.  Flame is overexposed and that''s a bit of a distraction, but overall I like it.</td>', 'I really like the creativity here!  I also really like the sharpness of the image in a challenge that seemed to be lacking a lot of sharp shots, overall.  Flame is overexposed and that''s a bit of a distraction, but overall I like it.', '2004-03-02 15:41:36.000000', NULL, 1),
(605880, 62650, 5391, '<td valign="top">It seems that the gamma on this shot is a little low, perhaps to camoflauge the burned out spots in the flames.  This is one of the more creative ideas of the challenge, though - great composition and use of the whole frame.  This idea would make an excellent stock piece.</td>', 'It seems that the gamma on this shot is a little low, perhaps to camoflauge the burned out spots in the flames.  This is one of the more creative ideas of the challenge, though - great composition and use of the whole frame.  This idea would make an excellent stock piece.', '2004-03-02 15:43:09.000000', NULL, 1),
(605883, 62583, 5391, '<td valign="top">Nice composition and a VERY creative shot!  One of the few that put a smile on my face while voting.  Nice work!  8</td>', 'Nice composition and a VERY creative shot!  One of the few that put a smile on my face while voting.  Nice work!  8', '2004-03-02 15:44:04.000000', NULL, 1),
(605885, 62776, 5391, '<td valign="top">This is an original idea that nobody else seemed to have and you''ve done it very nicely!  I almost feel like the focus is on the burger rather than the flame, but overall it''s a good shot.  Makes me hungry for a burger!  :)</td>', 'This is an original idea that nobody else seemed to have and you''ve done it very nicely!  I almost feel like the focus is on the burger rather than the flame, but overall it''s a good shot.  Makes me hungry for a burger!  :)', '2004-03-02 15:45:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(605886, 62759, 5391, '<td valign="top">Beautiful, moody shot.  I will have to remember to show this to my husband - he''s a big antique fan and I know he''ll like this.  I love the square composition and use of the full frame - the only nit-pick I''d have is the slightly blown out spot on the rim.  It doesn''t bother me that the flame is a bit burned out because, well, it''s a flame and it''s very small and it definitely gives you the feeling of the light and heat, but that tiny portion of the rim distracts me a bit.</td>', 'Beautiful, moody shot.  I will have to remember to show this to my husband - he''s a big antique fan and I know he''ll like this.  I love the square composition and use of the full frame - the only nit-pick I''d have is the slightly blown out spot on the rim.  It doesn''t bother me that the flame is a bit burned out because, well, it''s a flame and it''s very small and it definitely gives you the feeling of the light and heat, but that tiny portion of the rim distracts me a bit.', '2004-03-02 15:47:51.000000', NULL, 1),
(605946, 62200, 8891, '<td valign="top">Like the colors on the glass produced by the flame and also the reflections under above and below the stem. The flames is not very focused, which I understand but it is just a bit too blurry I guess because of its movement during the exposure. Oh well.  Fairly nice otherwise and I do love those reflections.</td>', 'Like the colors on the glass produced by the flame and also the reflections under above and below the stem. The flames is not very focused, which I understand but it is just a bit too blurry I guess because of its movement during the exposure. Oh well.  Fairly nice otherwise and I do love those reflections.', '2004-03-02 17:34:07.000000', NULL, 1),
(605948, 62614, 8891, '<td valign="top">just enough roundness to let me know this is the sun. I like the composition and the backlighting and the waning light on the clouds.  But the tone you chose...I not really a fan of that. Different.</td>', 'just enough roundness to let me know this is the sun. I like the composition and the backlighting and the waning light on the clouds.  But the tone you chose...I not really a fan of that. Different.', '2004-03-02 17:36:04.000000', NULL, 1),
(605949, 62767, 8891, '<td valign="top">for my feeling this is very nice except for the pink stripe running down the middle. The challenge rules do permit you to get rid of that some how or other and I wish it was not their cause it is very distracting.</td>', 'for my feeling this is very nice except for the pink stripe running down the middle. The challenge rules do permit you to get rid of that some how or other and I wish it was not their cause it is very distracting.', '2004-03-02 17:38:09.000000', NULL, 1),
(605950, 62359, 8891, '<td valign="top">I will assume the fire is from a match or a lighter but it is so small it is barely discernible. Nice idea but needs some oomp. The eyes are very nice and the rest of the image is quite fine.</td>', 'I will assume the fire is from a match or a lighter but it is so small it is barely discernible. Nice idea but needs some oomp. The eyes are very nice and the rest of the image is quite fine.', '2004-03-02 17:39:55.000000', NULL, 1),
(605955, 62728, 8891, '<td valign="top">nice picture....like what I call Sobrito water, that digital velvia effect you produce with the closed shutter and long exposure, I think.  Well now what challenge is this....mundane, Open, design....Oh yes FIRE.....sorry like to see the inference cause it is a fine image but I am totally missing it.</td>', 'nice picture....like what I call Sobrito water, that digital velvia effect you produce with the closed shutter and long exposure, I think.  Well now what challenge is this....mundane, Open, design....Oh yes FIRE.....sorry like to see the inference cause it is a fine image but I am totally missing it.', '2004-03-02 17:42:10.000000', NULL, 1),
(605956, 62569, 8891, '<td valign="top">the definition on the match is flawless, but the flame needed better focus IMO.</td>', 'the definition on the match is flawless, but the flame needed better focus IMO.', '2004-03-02 17:43:04.000000', NULL, 1),
(605959, 62700, 8891, '<td valign="top">bit too abstract for me...the most interesting part to me is the neat texture at the base of the flame....this flame does not work for me although it is nice in the area over the texture.</td>', 'bit too abstract for me...the most interesting part to me is the neat texture at the base of the flame....this flame does not work for me although it is nice in the area over the texture.', '2004-03-02 17:44:34.000000', NULL, 1),
(605964, 62819, 8891, '<td valign="top">ahh....sobrito flames eh....I think the long exposure closed lense works better when things flow continuously in one direction.  Flames or fire is fairly well all over the place. I would rather see fire sharp and seering and not pale and ghost like.</td>', 'ahh....sobrito flames eh....I think the long exposure closed lense works better when things flow continuously in one direction.  Flames or fire is fairly well all over the place. I would rather see fire sharp and seering and not pale and ghost like.', '2004-03-02 17:46:48.000000', NULL, 1),
(605972, 62324, 8891, '<td valign="top">I tried this with some red, orange and yellow gerbera daisies and end up using the smudge brush to make the petals appear more flame like. This, however, is quite nice without such histrionics.  I wish the back ground was either one of the colors of the flowers or black, the white is hurting my eyes against the wonderful bright colors of the flowers.</td>', 'I tried this with some red, orange and yellow gerbera daisies and end up using the smudge brush to make the petals appear more flame like. This, however, is quite nice without such histrionics.  I wish the back ground was either one of the colors of the flowers or black, the white is hurting my eyes against the wonderful bright colors of the flowers.', '2004-03-02 17:52:09.000000', NULL, 1),
(606011, 62583, 327, '<td valign="top">Hi there. After looking at this for two days....yes, paper plane in a fire.  It just doesn''t spark interest. I think technically  the shot is fine. Your weakness is the composition. The activity in the background is a distraction. Good luck to you in the challenge.</td>', 'Hi there. After looking at this for two days....yes, paper plane in a fire.  It just doesn''t spark interest. I think technically  the shot is fine. Your weakness is the composition. The activity in the background is a distraction. Good luck to you in the challenge.', '2004-03-02 18:38:09.000000', NULL, 1),
(606013, 62434, 327, '<td valign="top">I think the idea was creative. The execution is a little weak. The lure is the color of the background and is lost. The worm, it''s okay but really doesn''t stand out or have much interest. The flames are very nice..they are a good color and appear to be moving, causing interest. Not a bad entry.</td>', 'I think the idea was creative. The execution is a little weak. The lure is the color of the background and is lost. The worm, it''s okay but really doesn''t stand out or have much interest. The flames are very nice..they are a good color and appear to be moving, causing interest. Not a bad entry.', '2004-03-02 18:39:48.000000', NULL, 1),
(606014, 62246, 327, '<td valign="top">I would only suggest a different crop the bottom dead space. Also that cropped off the top of the flames. Nice idea, love the blue.</td>', 'I would only suggest a different crop the bottom dead space. Also that cropped off the top of the flames. Nice idea, love the blue.', '2004-03-02 18:40:39.000000', NULL, 1),
(606015, 62814, 327, '<td valign="top">I think if we were closer to the action this would of had more interest. As it is here, just seems too far away, too small. The idea was good.</td>', 'I think if we were closer to the action this would of had more interest. As it is here, just seems too far away, too small. The idea was good.', '2004-03-02 18:41:43.000000', NULL, 1),
(606023, 62614, 11843, '<td valign="top">I like this a lot. The colors you chose appeal to me. I think you could have cropped some off the left hand side. My eye is drawn to the dark area because it seems so dominant. Good luck. 8</td>', 'I like this a lot. The colors you chose appeal to me. I think you could have cropped some off the left hand side. My eye is drawn to the dark area because it seems so dominant. Good luck. 8', '2004-03-02 18:54:00.000000', NULL, 1),
(606024, 62570, 6600, '<td valign="top">Nicely exposed, very sharp and clear.  Super job framing it up!  Desaturating all but the fire was a neat touch, nicely done.  Should do well.  DSLR?</td>', 'Nicely exposed, very sharp and clear.  Super job framing it up!  Desaturating all but the fire was a neat touch, nicely done.  Should do well.  DSLR?', '2004-03-02 18:55:41.000000', NULL, 1),
(606026, 62823, 16912, '<td valign="top">Love it! <br/>I see you needed validation (after I voted) can''t wait to see how you did this. If I put my ''picky'' head on the button on the cuff is a little distracting</td>', 'Love it! I see you needed validation (after I voted) can''t wait to see how you did this. If I put my ''picky'' head on the button on the cuff is a little distracting', '2004-03-02 18:58:30.000000', NULL, 1),
(606030, 62371, 6600, '<td valign="top">Super clear and sharp (DSLR?), very nice composition, colors are spot on.  Great job!  Should do very well. -  My initial thoughts were that you  carefully placed a sparkler behind the plug, but I believe it would have produced to much smoke.  What puzzles me is that the sparks are flying outward in a circular pattern, not sure how I would have accomplished that.... (maybe an extended exposure would have allowed enough time to produce it?).  I will have to check back after the challenge.  Again..... great job!</td>', 'Super clear and sharp (DSLR?), very nice composition, colors are spot on.  Great job!  Should do very well. -  My initial thoughts were that you  carefully placed a sparkler behind the plug, but I believe it would have produced to much smoke.  What puzzles me is that the sparks are flying outward in a circular pattern, not sure how I would have accomplished that.... (maybe an extended exposure would have allowed enough time to produce it?).  I will have to check back after the challenge.  Again..... great job!', '2004-03-02 19:07:25.000000', NULL, 1),
(606053, 62820, 6600, '<td valign="top">Creative idea, simple title, nicely done, will do well, good job! - I might have introduced a touch more light on the front of the pepper to ''expose'' more detail.</td>', 'Creative idea, simple title, nicely done, will do well, good job! - I might have introduced a touch more light on the front of the pepper to ''expose'' more detail.', '2004-03-02 19:51:56.000000', NULL, 1),
(606055, 62122, 6600, '<td valign="top">Great composition and exposure, very well titled (simple), nice job!</td>', 'Great composition and exposure, very well titled (simple), nice job!', '2004-03-02 19:55:21.000000', NULL, 1),
(606067, 62823, 6678, '<td valign="top">Now that really is clever.</td>', 'Now that really is clever.', '2004-03-02 20:16:00.000000', NULL, 1),
(606070, 62240, 6678, '<td valign="top">That must have been fun :o)</td>', 'That must have been fun :o)', '2004-03-02 20:17:53.000000', NULL, 1),
(606071, 62770, 6678, '<td valign="top">Clever, very clever. I like it</td>', 'Clever, very clever. I like it', '2004-03-02 20:18:33.000000', NULL, 1),
(606093, 62200, 7556, '<td valign="top">Nice lighting and good focus...pretty picture...</td>', 'Nice lighting and good focus...pretty picture...', '2004-03-02 21:25:19.000000', NULL, 1),
(606096, 62431, 16230, '<td valign="top">Wow, I really like this image! Vibrant colors, nice composition--it works! Although, youre probably going to get slammed for doing something so non-conformist, I applaud you for it. Good job!<br/> <br/>P.S. I think it would have been fine without the border. It''s not a big deal to me, I just don''t think it adds anything to the image.</td>', 'Wow, I really like this image! Vibrant colors, nice composition--it works! Although, youre probably going to get slammed for doing something so non-conformist, I applaud you for it. Good job! P.S. I think it would have been fine without the border. It''s not a big deal to me, I just don''t think it adds anything to the image.', '2004-03-02 21:28:44.000000', NULL, 1),
(606133, 62238, 8891, '<td valign="top">Sorry just not happening for me.  Fire is bright enough even in a dark room that it should not need all the long exposure shots that I am seeing so far.  Just makes everythiing look blurry because fire is not static enough.</td>', 'Sorry just not happening for me.  Fire is bright enough even in a dark room that it should not need all the long exposure shots that I am seeing so far.  Just makes everythiing look blurry because fire is not static enough.', '2004-03-02 22:04:13.000000', NULL, 1),
(606134, 62802, 8891, '<td valign="top">This is the best rendition of fire so far, for my tastes.  Clear and sharp...maybe the glass has something to do with it.  I would like to see the full dark areas down away with or downsized on the right and top.  Other than that pretty fine. Like this as abstract very much.</td>', 'This is the best rendition of fire so far, for my tastes.  Clear and sharp...maybe the glass has something to do with it.  I would like to see the full dark areas down away with or downsized on the right and top.  Other than that pretty fine. Like this as abstract very much.', '2004-03-02 22:06:38.000000', NULL, 1),
(606136, 62815, 8891, '<td valign="top">way bright and not enough flame.</td>', 'way bright and not enough flame.', '2004-03-02 22:07:12.000000', NULL, 1),
(606139, 62431, 8891, '<td valign="top">the colors are not very appealing to me, hot pink purple and blue?  Ahh that''s better I have my sunglasses on....yeesh with the colors.</td>', 'the colors are not very appealing to me, hot pink purple and blue?  Ahh that''s better I have my sunglasses on....yeesh with the colors.', '2004-03-02 22:08:19.000000', NULL, 1),
(606144, 62772, 8891, '<td valign="top">more sparks the fire but the great thin curls of smoke out weigh that....hate to say more focue but well....just a littlemore. cause the smoke is acutally a lot more interesting to me than the bits of flame and the sparks.</td>', 'more sparks the fire but the great thin curls of smoke out weigh that....hate to say more focue but well....just a littlemore. cause the smoke is acutally a lot more interesting to me than the bits of flame and the sparks.', '2004-03-02 22:09:56.000000', NULL, 1),
(606148, 62818, 8891, '<td valign="top">ok...now that mallow is en fuego.  Nice  good cop.  Like the little wisp of smoke and the falmes is inordinately in some sort of focus:  THANK YOU!</td>', 'ok...now that mallow is en fuego.  Nice  good cop.  Like the little wisp of smoke and the falmes is inordinately in some sort of focus:  THANK YOU!', '2004-03-02 22:11:11.000000', NULL, 1),
(606151, 62287, 8891, '<td valign="top">Ok now this is GREAT....whatever did you blow up and where and where do you live that you could get away with it wihout someone diming you out!   Excellent! clear and sharp wonderful colors, shapes, lights......WOW! my only 10 so far....my only thing above a 8 so far.  REALLY GREAT!!!!</td>', 'Ok now this is GREAT....whatever did you blow up and where and where do you live that you could get away with it wihout someone diming you out!   Excellent! clear and sharp wonderful colors, shapes, lights......WOW! my only 10 so far....my only thing above a 8 so far.  REALLY GREAT!!!!', '2004-03-02 22:13:46.000000', NULL, 1),
(606153, 62783, 3306, '<td valign="top">Very good. My favorite of the challenge. 10</td>', 'Very good. My favorite of the challenge. 10', '2004-03-02 22:15:48.000000', NULL, 1),
(606154, 62823, 8891, '<td valign="top">Now that''s a wonder....how to...how to.!!!!  10</td>', 'Now that''s a wonder....how to...how to.!!!!  10', '2004-03-02 22:16:13.000000', NULL, 1),
(606155, 62823, 3306, '<td valign="top">Well done. Top 5. I will enjoy reading your technique.</td>', 'Well done. Top 5. I will enjoy reading your technique.', '2004-03-02 22:16:42.000000', NULL, 1),
(606164, 62783, 13728, '<td valign="top">Very interesting, would love the detail on how you did this</td>', 'Very interesting, would love the detail on how you did this', '2004-03-02 22:25:41.000000', NULL, 1),
(606169, 62728, 13728, '<td valign="top">Did the water put out the fire??  Beautiful shot but just doesn''t meet the chalenge</td>', 'Did the water put out the fire??  Beautiful shot but just doesn''t meet the chalenge', '2004-03-02 22:27:42.000000', NULL, 1),
(606170, 62522, 13728, '<td valign="top">funny shot  . . .or maybe not funy but painful</td>', 'funny shot  . . .or maybe not funy but painful', '2004-03-02 22:28:34.000000', NULL, 1),
(606172, 62240, 13728, '<td valign="top">You must have really hated that priner...must have been an HP</td>', 'You must have really hated that priner...must have been an HP', '2004-03-02 22:29:18.000000', NULL, 1),
(606174, 62411, 13728, '<td valign="top">Nice shot, but I think the angle is distracting</td>', 'Nice shot, but I think the angle is distracting', '2004-03-02 22:31:26.000000', NULL, 1),
(606177, 62221, 13728, '<td valign="top">Nice capture.  Looks like there might have been some photoshopping, which I wonder if you arent getting slammed for...but I like this image and what you have done with it very much</td>', 'Nice capture.  Looks like there might have been some photoshopping, which I wonder if you arent getting slammed for...but I like this image and what you have done with it very much', '2004-03-02 22:35:57.000000', NULL, 1),
(606179, 62583, 13728, '<td valign="top">Hope no one was injured here...Like any paper dolls!</td>', 'Hope no one was injured here...Like any paper dolls!', '2004-03-02 22:38:28.000000', NULL, 1),
(606181, 62823, 13728, '<td valign="top">Clever, hope you included details</td>', 'Clever, hope you included details', '2004-03-02 22:39:25.000000', NULL, 1),
(606196, 62595, 2752, '<td valign="top">You certainly got the shot at the exact moment of ignition.  Great job.  I love the white vapors  The black background makes a very striking composition.(9)</td>', 'You certainly got the shot at the exact moment of ignition.  Great job.  I love the white vapors  The black background makes a very striking composition.(9)', '2004-03-02 22:47:50.000000', NULL, 1),
(606226, 62475, 2752, '<td valign="top">very nice composition..I like the black foreground and the grayblue background,both cool colors and the hot flame in  contrast. Nice play of straight and curved lines.</td>', 'very nice composition..I like the black foreground and the grayblue background,both cool colors and the hot flame in  contrast. Nice play of straight and curved lines.', '2004-03-02 22:59:11.000000', NULL, 1),
(606232, 62820, 2752, '<td valign="top">great capture of the ''hot'' pepper aflamed on a cold metal fork. The black background  adds to the composition.</td>', 'great capture of the ''hot'' pepper aflamed on a cold metal fork. The black background  adds to the composition.', '2004-03-02 23:02:25.000000', NULL, 1),
(606250, 62767, 2752, '<td valign="top">this really conveys heat.  I especially like the white vapor escaping from the depths.  Well done.(10)</td>', 'this really conveys heat.  I especially like the white vapor escaping from the depths.  Well done.(10)', '2004-03-02 23:06:25.000000', NULL, 1),
(606270, 62759, 4258, '<td valign="top">A nice picture - would have liked the DoF to be deep enough to keep the knob sharp</td>', 'A nice picture - would have liked the DoF to be deep enough to keep the knob sharp', '2004-03-02 23:19:44.000000', NULL, 1),
(606284, 62823, 15305, '<td valign="top">Beatiful shot, great idea and composition.</td>', 'Beatiful shot, great idea and composition.', '2004-03-02 23:29:04.000000', NULL, 1),
(606286, 62711, 15305, '<td valign="top">Nice idea and interesting composition.</td>', 'Nice idea and interesting composition.', '2004-03-02 23:30:06.000000', NULL, 1),
