(606303, 62749, 6600, '<td valign="top">Clear and sharp, nicely done!  Good Luck.</td>', 'Clear and sharp, nicely done!  Good Luck.', '2004-03-02 23:45:49.000000', NULL, 1),
(606761, 62445, 16297, '<td valign="top">Great composition and contrast light.</td>', 'Great composition and contrast light.', '2004-03-03 03:41:53.000000', NULL, 1),
(606828, 62783, 15920, '<td valign="top">There is some imperfection visible on the back of the ball, but, not bad.This is my favorite of the competition.  I hope you win.<br/> <br/></td>', 'There is some imperfection visible on the back of the ball, but, not bad.This is my favorite of the competition.  I hope you win. ', '2004-03-03 05:52:40.000000', NULL, 1),
