INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(608748, 62700, 10818, '<td valign="top">I hope all the voters look at it long enough to get it....very nice shot....</td>', 'I hope all the voters look at it long enough to get it....very nice shot....', '2004-03-04 00:03:03.000000', NULL, 1),
(608777, 62649, 14476, '<td valign="top">This is a terrific take on the Challenge.  While I suppose it would have been ''better'' to have the foreground berries in focus, the photograph is still worth a 10.</td>', 'This is a terrific take on the Challenge.  While I suppose it would have been ''better'' to have the foreground berries in focus, the photograph is still worth a 10.', '2004-03-04 01:26:51.000000', NULL, 1),
(608778, 62324, 14476, '<td valign="top">Love your flaming flowers.  They are a perfect take on the Challenge and beautifully presented. Easily worth a 10.</td>', 'Love your flaming flowers.  They are a perfect take on the Challenge and beautifully presented. Easily worth a 10.', '2004-03-04 01:27:35.000000', NULL, 1),
(608779, 62434, 14476, '<td valign="top">Incredibly well photographed and a super take on the Challenge.  You easily get a 10 from me and I hope others see the beauty of this as well.  Great!</td>', 'Incredibly well photographed and a super take on the Challenge.  You easily get a 10 from me and I hope others see the beauty of this as well.  Great!', '2004-03-04 01:28:47.000000', NULL, 1),
(608781, 62430, 14476, '<td valign="top">As you undoubtedly know, there are several incinerated marshmallows in the Challenge.  I think you did yours best.  It''s still edible for one, which means you got it right the first time, or had a good backup supply!  Kidding aside, it''s a good image and well worth a 9.</td>', 'As you undoubtedly know, there are several incinerated marshmallows in the Challenge.  I think you did yours best.  It''s still edible for one, which means you got it right the first time, or had a good backup supply!  Kidding aside, it''s a good image and well worth a 9.', '2004-03-04 01:32:59.000000', NULL, 1),
(608783, 62780, 14476, '<td valign="top">A very pleasant and original take on the Challenge.  Probably a touch over exposed, but still good.  8</td>', 'A very pleasant and original take on the Challenge.  Probably a touch over exposed, but still good.  8', '2004-03-04 01:33:55.000000', NULL, 1),
(608784, 62673, 14476, '<td valign="top">I wrote a comment for this once, but it disappeared.  If you get two comments from me, they both will say this is a nice original take on the Challenge and well worth a 10.</td>', 'I wrote a comment for this once, but it disappeared.  If you get two comments from me, they both will say this is a nice original take on the Challenge and well worth a 10.', '2004-03-04 01:35:33.000000', NULL, 1),
(608809, 62750, 6130, '<td valign="top">Good imagination.</td>', 'Good imagination.', '2004-03-04 04:08:02.000000', NULL, 1),
(608831, 62767, 18056, '<td valign="top">Excellent!!</td>', 'Excellent!!', '2004-03-04 04:57:28.000000', NULL, 1),
(608844, 62646, 10084, '<td valign="top">Diagonal position of the lighter makes for an interesting subject. A darker background would make the flame prominent.</td>', 'Diagonal position of the lighter makes for an interesting subject. A darker background would make the flame prominent.', '2004-03-04 05:07:07.000000', NULL, 1),
(608850, 62700, 10084, '<td valign="top">Love the beautiful shape of the flame. I like how your eyes are lead from the bottom toward the top following the curves. Nice simple composition. I say ditch the white frame, it interferes with the composition. I don''t take off points for frames. "10"</td>', 'Love the beautiful shape of the flame. I like how your eyes are lead from the bottom toward the top following the curves. Nice simple composition. I say ditch the white frame, it interferes with the composition. I don''t take off points for frames. "10"', '2004-03-04 05:11:14.000000', NULL, 1),
(608852, 62324, 10084, '<td valign="top">Wonderful take on the fire theme using flowers. Great dynamic composition. Looks almost like rising flames.Very vibrant colors. "10"</td>', 'Wonderful take on the fire theme using flowers. Great dynamic composition. Looks almost like rising flames.Very vibrant colors. "10"', '2004-03-04 05:12:46.000000', NULL, 1),
(608855, 62565, 10084, '<td valign="top">Interesting subject. Clearly photographed.  Too much negative space for your eyes to wonder around . Would like to see a vertical crop so the subject would be the focus. "8"</td>', 'Interesting subject. Clearly photographed.  Too much negative space for your eyes to wonder around . Would like to see a vertical crop so the subject would be the focus. "8"', '2004-03-04 05:14:31.000000', NULL, 1),
(608856, 62589, 10084, '<td valign="top">Very interesting and dynamic flame. Vertical composition helps to keep the subject in focus."9"</td>', 'Very interesting and dynamic flame. Vertical composition helps to keep the subject in focus."9"', '2004-03-04 05:15:42.000000', NULL, 1),
(608858, 62643, 10084, '<td valign="top">The black frame works perfectly to capture the inpredictabity of the flame. Good example of filling the frame composition. "8"</td>', 'The black frame works perfectly to capture the inpredictabity of the flame. Good example of filling the frame composition. "8"', '2004-03-04 05:17:27.000000', NULL, 1),
(608859, 62819, 10084, '<td valign="top">Composition is interesting with the depth of field of the flames. Your eyes are lead from the 3 flames in the foreground to the 1 in the back.</td>', 'Composition is interesting with the depth of field of the flames. Your eyes are lead from the 3 flames in the foreground to the 1 in the back.', '2004-03-04 05:18:37.000000', NULL, 1),
(608884, 62359, 11897, '<td valign="top">very nice idea, bigger reflections would improve it.</td>', 'very nice idea, bigger reflections would improve it.', '2004-03-04 05:43:17.000000', NULL, 1),
(608887, 62724, 11897, '<td valign="top">needs to be a little sharper.I like the composition and the idea.</td>', 'needs to be a little sharper.I like the composition and the idea.', '2004-03-04 05:45:35.000000', NULL, 1),
(608888, 62725, 11897, '<td valign="top">very good.</td>', 'very good.', '2004-03-04 05:46:40.000000', NULL, 1),
