(608916, 62673, 10084, '<td valign="top">One of the most original . Great composition. Lighting is subtle but works because of the great colors in the subject.The black background really helps to make it pop out of the shot."10"</td>', 'One of the most original . Great composition. Lighting is subtle but works because of the great colors in the subject.The black background really helps to make it pop out of the shot."10"', '2004-03-04 06:57:58.000000', NULL, 1),
(608921, 62392, 10084, '<td valign="top">Simple composition. The great blue colors are vibrant and brilliant. Love the dark heating element in the center, makes it seem like a flower. "10"</td>', 'Simple composition. The great blue colors are vibrant and brilliant. Love the dark heating element in the center, makes it seem like a flower. "10"', '2004-03-04 07:00:06.000000', NULL, 1),
(608924, 62569, 10084, '<td valign="top">Great closeup of the match. Incredible details. The flame has a brilliant, vibrant color. The black background really helps to set the subject and the bakcground apart. Quite a bit of negative space. I believe cropping a bit off of the left would make it a better composition, but that''s minor. "10"</td>', 'Great closeup of the match. Incredible details. The flame has a brilliant, vibrant color. The black background really helps to set the subject and the bakcground apart. Quite a bit of negative space. I believe cropping a bit off of the left would make it a better composition, but that''s minor. "10"', '2004-03-04 07:01:53.000000', NULL, 1),
(609219, 62431, 14614, '<td valign="top">LIke your creative take on the theme.  Colors are interesting and the abstract quality make the shot for me.  Only negative is your border - something about the while part detacts from the white in the shot.</td>', 'LIke your creative take on the theme.  Colors are interesting and the abstract quality make the shot for me.  Only negative is your border - something about the while part detacts from the white in the shot.', '2004-03-04 11:24:57.000000', NULL, 1),
