(609223, 62700, 14614, '<td valign="top">Whte border doesn''t work for me - takes away from the white hot paint with light effect.  Otherwise, nice composition and abstract quality.</td>', 'Whte border doesn''t work for me - takes away from the white hot paint with light effect.  Otherwise, nice composition and abstract quality.', '2004-03-04 11:26:45.000000', NULL, 1),
(609225, 62791, 14614, '<td valign="top">I like the image and the creativity.  White border distracts, Imho</td>', 'I like the image and the creativity.  White border distracts, Imho', '2004-03-04 11:27:59.000000', NULL, 1),
(609227, 62557, 14614, '<td valign="top">Extra credit for creativity here.</td>', 'Extra credit for creativity here.', '2004-03-04 11:29:00.000000', NULL, 1),
