(613538, 62595, 3306, '<td valign="top">Your are the Babe Ruth of DPChallenge! Congratulations on another fantastic shot.</td>', 'Your are the Babe Ruth of DPChallenge! Congratulations on another fantastic shot.', '2004-03-08 05:58:28.000000', NULL, 0),
(613540, 62526, 14603, '<td valign="top">This was a good idea that, in my opinion, deserved to finish higher.<br/> <br/>Gordon</td>', 'This was a good idea that, in my opinion, deserved to finish higher. Gordon', '2004-03-08 06:02:10.000000', NULL, 0),
(613541, 62595, 5728, '<td valign="top">Wow a bluey!!! Thanks for all your comments and votes, really appreciated. I am on holiday in Mallorca at the moment but I just had to find an internet cafe to see how I fared :)<br/> <br/>I took about 40 shots of this to get it the way I wanted. Basically it is 3 match sticks in a clamp. You can actually see the match stick behind the first one, which unfortunately gives the front one an oversharpened look to it. I dipped the match sticks in olive oil to get a good amount of smoke. I used a lighter in one hand and the shutter cable in the other hand and lit the match sticks behind the first one so that I had enough reaction time to take a photo when the first match stick lit up. I used a black background and two soft boxes from each side.<br/> <br/>So, now I am back off into the Mediterranean sun :)<br/><br/><i>Message edited by author 2004-03-08 06:08:34.</i></td>', 'Wow a bluey!!! Thanks for all your comments and votes, really appreciated. I am on holiday in Mallorca at the moment but I just had to find an internet cafe to see how I fared :) I took about 40 shots of this to get it the way I wanted. Basically it is 3 match sticks in a clamp. You can actually see the match stick behind the first one, which unfortunately gives the front one an oversharpened look to it. I dipped the match sticks in olive oil to get a good amount of smoke. I used a lighter in one hand and the shutter cable in the other hand and lit the match sticks behind the first one so that I had enough reaction time to take a photo when the first match stick lit up. I used a black background and two soft boxes from each side. So, now I am back off into the Mediterranean sun :)', '2004-03-08 06:07:48.000000', '2004-03-08 06:08:34.000000', 0),
(613542, 62728, 14603, '<td valign="top">This is your second challenge entry recently that has been deliberately way off the theme....Is there some kind of voter pattern test going on ?When are you letting us into the plot John ?</td>', 'This is your second challenge entry recently that has been deliberately way off the theme....Is there some kind of voter pattern test going on ?When are you letting us into the plot John ?', '2004-03-08 06:11:21.000000', NULL, 0),
